SELECT ma.major_name, COUNT(DISTINCT m.member_id) as engaged_member_count, COUNT(DISTINCT a.link_to_event) as total_events_attended, AVG(CASE WHEN a.link_to_member IS NOT NULL THEN 1 ELSE 0 END) * 100 as engagement_rate FROM member m JOIN major ma ON m.link_to_major = ma.major_id LEFT JOIN attendance a ON a.link_to_member = m.member_id GROUP BY m.member_id, ma.major_name ORDER BY engaged_member_count DESC LIMIT 10;
